import{renderTitleMenu,titleDefaults,titleDesignerMarkup,bindTitleDesigner}from'./title-menu.js';
import{indieIdeas}from'./indie-presets.js';
import{getGameVolume,setGameVolume}from'./sound-editor.js';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function renderGameTitle(element,project,callbacks){renderTitleMenu(element,project,callbacks)}
export function openGameSettings(project,notify){
 const d=document.createElement('dialog');d.className='game-settings editor-dialog';d.innerHTML=`<div class="dialog-top"><h2>Game settings</h2><button id="close-game-settings" aria-label="Close game settings">×</button></div><label>Sound volume<input id="game-volume" type="range" min="0" max="1" step=".05" value="${getGameVolume()}"></label><button id="game-fullscreen">Toggle fullscreen</button><h3>Controls</h3><div class="settings-controls">${Object.entries(project.inputs||{left:'ArrowLeft / A',right:'ArrowRight / D',jump:'Space',up:'ArrowUp / W',down:'ArrowDown / S'}).map(([action,key])=>`<div><span>${esc(action)}</span><kbd>${esc(key)}</kbd></div>`).join('')}</div><p>Touch controls appear during play on phones.</p>`;document.body.append(d);d.querySelector('#close-game-settings').onclick=()=>d.close();d.querySelector('#game-volume').oninput=e=>setGameVolume(e.target.value);d.querySelector('#game-fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else if(document.documentElement.requestFullscreen)await document.documentElement.requestFullscreen();else notify('Fullscreen is available from your browser’s menu.')}catch{notify('Your browser did not allow fullscreen.')}};d.onclose=()=>d.remove();d.showModal();
}
export function openPresentationEditor({project,tab='title',onApply,notify}){
 const d=document.createElement('dialog');d.className='presentation-editor editor-dialog';const original=titleDefaults(project);let logo=original.logo,artwork=original.artwork,background=project.backgroundAsset;
 d.innerHTML=`<div class="dialog-top"><h2>Game presentation</h2><button id="close-presentation" aria-label="Close presentation editor">×</button></div><div class="presentation-tabs"><button data-tab="title">Title screen</button><button data-tab="scene">Scene appearance</button></div><form id="presentation-form"><section id="presentation-title"><label class="check"><input id="title-enabled" type="checkbox" ${original.enabled?'checked':''}>Show title screen before the game</label><label>Game title<input id="title-text" maxlength="80" value="${esc(original.title||project.name)}"></label><label>Subtitle (optional)<input id="title-subtitle" maxlength="160" value="${esc(original.subtitle||'')}"></label><div class="game-size-grid"><label>Play button<input id="title-play-label" maxlength="24" value="${esc(original.playLabel||'Play')}"></label><label>Accent color<input id="title-accent" type="color" value="${original.accent||'#ab88d3'}"></label></div><label class="check"><input id="title-multiplayer" type="checkbox" ${original.multiplayer?'checked':''}>Play with friends button</label><label class="check"><input id="title-settings" type="checkbox" ${original.settings!==false?'checked':''}>Settings button</label>${titleDesignerMarkup()}<label>Logo image<input type="file" id="title-logo-file" accept="image/png,image/jpeg,image/webp"></label><div class="artwork-preview"><img id="title-logo-preview" alt="Logo preview" ${logo?`src="${logo}"`:'hidden'}><button id="remove-title-logo" type="button">Remove logo</button></div><label>Title artwork<input type="file" id="title-artwork-file" accept="image/png,image/jpeg,image/webp"></label><div class="artwork-preview"><img id="title-artwork-preview" alt="Title artwork preview" ${artwork?`src="${artwork}"`:'hidden'}><button id="remove-title-artwork" type="button">Remove artwork</button></div></section><section id="presentation-scene"><label>Scene theme<select id="scene-theme"><option value="classic">Classic blue sky</option>${Object.entries(indieIdeas).map(([id,name])=>`<option value="${id}">${name}</option>`).join('')}</select></label><label>Image rendering<select id="render-style"><option value="pixel">Pixel art</option><option value="smooth">Smooth artwork</option></select></label><label>Background image<input id="scene-background-file" type="file" accept="image/png,image/jpeg,image/webp"></label><div class="artwork-preview"><img id="scene-background-preview" alt="Scene background preview" ${background?`src="${background}"`:'hidden'}><button id="remove-scene-background" type="button">Remove background</button></div></section><div class="presentation-actions"><button type="button" id="save-preview-title">Save & preview title</button><button type="submit" class="primary">Save changes</button></div></form>`;
 document.body.append(d);const $=s=>d.querySelector(s);$('#scene-theme').value=project.theme||Object.hasOwn(indieIdeas,project.template)&&project.template||'classic';$('#render-style').value=project.renderStyle||'pixel';
 const setTab=which=>{$('#presentation-title').hidden=which!=='title';$('#presentation-scene').hidden=which!=='scene';d.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===which))};d.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>setTab(b.dataset.tab));setTab(tab);
 const load=(selector,preview,set)=>{$(selector).onchange=async e=>{const file=e.target.files[0];if(!file)return;if(file.size>1500000||!['image/png','image/jpeg','image/webp'].includes(file.type)){notify('Choose a PNG, JPEG or WebP image under 1.5 MB.');return}try{const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file)});set(data);$(preview).src=data;$(preview).hidden=false}catch{notify('Could not import that image.')}}};load('#title-logo-file','#title-logo-preview',v=>logo=v);load('#title-artwork-file','#title-artwork-preview',v=>artwork=v);load('#scene-background-file','#scene-background-preview',v=>background=v);
 for(const[id,preview,set]of [['#remove-title-logo','#title-logo-preview',()=>logo=undefined],['#remove-title-artwork','#title-artwork-preview',()=>artwork=undefined],['#remove-scene-background','#scene-background-preview',()=>background=undefined]])$(id).onclick=()=>{set();$(preview).hidden=true;$(preview).removeAttribute('src')};
 const getDesign=bindTitleDesigner(d,project,original,()=>{logo=undefined;artwork=undefined;$('#title-logo-preview').hidden=true;$('#title-artwork-preview').hidden=true},notify);const save=preview=>{try{const design=getDesign();const title=$('#title-text').value.trim()||project.name;onApply({titleScreen:{enabled:$('#title-enabled').checked,title,subtitle:$('#title-subtitle').value,playLabel:$('#title-play-label').value.trim()||'Play',accent:$('#title-accent').value,multiplayer:$('#title-multiplayer').checked,settings:$('#title-settings').checked,logo,artwork,...design},theme:$('#scene-theme').value,renderStyle:$('#render-style').value,backgroundAsset:background},preview);d.close()}catch(error){notify(error.message)}};$('#presentation-form').onsubmit=e=>{e.preventDefault();save(false)};$('#save-preview-title').onclick=()=>save(true);$('#close-presentation').onclick=()=>d.close();d.onclose=()=>d.remove();d.showModal();
}
